CREATE EXTENSION IF NOT EXISTS postgis;
CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE organizations(id uuid PRIMARY KEY, name text NOT NULL);
CREATE TABLE users(id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations, email text NOT NULL UNIQUE, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('admin','operator','viewer')), enabled boolean NOT NULL DEFAULT true);
CREATE TABLE sessions(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, csrf_token text NOT NULL, expires_at timestamptz NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE realtime_tickets(token_hash text PRIMARY KEY, session_hash text NOT NULL REFERENCES sessions ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE TABLE vehicles(id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations, name text NOT NULL, registration_number text NOT NULL, registration_key text NOT NULL, vehicle_type text NOT NULL, notes text NOT NULL DEFAULT '', enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,registration_key), UNIQUE(organization_id,id));
CREATE TABLE devices(id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations, imei text NOT NULL UNIQUE CHECK(imei ~ '^[0-9]{15}$'), manufacturer text NOT NULL, model text NOT NULL, firmware text NOT NULL DEFAULT '', protocol text NOT NULL, profile_id text NOT NULL, expected_interval integer NOT NULL CHECK(expected_interval BETWEEN 5 AND 86400), enabled boolean NOT NULL DEFAULT true, last_received_at timestamptz, UNIQUE(organization_id,id));
CREATE TABLE vehicle_device_assignments(id uuid PRIMARY KEY, organization_id uuid NOT NULL, device_id uuid NOT NULL, vehicle_id uuid NOT NULL, valid_from timestamptz NOT NULL, valid_to timestamptz, CHECK(valid_to IS NULL OR valid_to>valid_from), FOREIGN KEY(organization_id,device_id) REFERENCES devices(organization_id,id), FOREIGN KEY(organization_id,vehicle_id) REFERENCES vehicles(organization_id,id), EXCLUDE USING gist(device_id WITH =,tstzrange(valid_from,valid_to,'[)') WITH &&), EXCLUDE USING gist(vehicle_id WITH =,tstzrange(valid_from,valid_to,'[)') WITH &&));
CREATE TABLE ingestion_receipts(event_id uuid PRIMARY KEY, organization_id uuid NOT NULL, device_id uuid NOT NULL, fingerprint text NOT NULL UNIQUE, received_at timestamptz NOT NULL, persisted_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE device_logs(id uuid PRIMARY KEY, event_id uuid NOT NULL UNIQUE REFERENCES ingestion_receipts(event_id), organization_id uuid NOT NULL, device_id uuid NOT NULL, vehicle_id uuid, received_at timestamptz NOT NULL, device_time timestamptz, protocol text NOT NULL, packet_type text NOT NULL, event_type text NOT NULL, decode_status text NOT NULL, checksum_status text NOT NULL, normalized_data jsonb NOT NULL, raw_data text, parser_version text NOT NULL, historical boolean NOT NULL, FOREIGN KEY(organization_id,device_id) REFERENCES devices(organization_id,id), FOREIGN KEY(organization_id,vehicle_id) REFERENCES vehicles(organization_id,id));
CREATE INDEX logs_org_time ON device_logs(organization_id,received_at DESC,id DESC);
CREATE INDEX logs_device_time ON device_logs(organization_id,device_id,received_at DESC,id DESC);
CREATE TABLE gps_points(id uuid PRIMARY KEY, event_id uuid NOT NULL UNIQUE REFERENCES ingestion_receipts(event_id), organization_id uuid NOT NULL, device_id uuid NOT NULL, vehicle_id uuid, device_time timestamptz NOT NULL, received_at timestamptz NOT NULL, position geometry(Point,4326) NOT NULL, speed_kph real, heading_degrees real, gps_valid boolean, historical boolean NOT NULL, FOREIGN KEY(organization_id,device_id) REFERENCES devices(organization_id,id), FOREIGN KEY(organization_id,vehicle_id) REFERENCES vehicles(organization_id,id));
CREATE INDEX points_vehicle_time ON gps_points(organization_id,vehicle_id,device_time DESC,id DESC);
CREATE TABLE vehicle_latest_state(vehicle_id uuid PRIMARY KEY, organization_id uuid NOT NULL, device_id uuid NOT NULL, position geometry(Point,4326), location_time timestamptz, ignition boolean, ignition_time timestamptz, last_received_at timestamptz NOT NULL, revision bigint NOT NULL DEFAULT 1, FOREIGN KEY(organization_id,vehicle_id) REFERENCES vehicles(organization_id,id), FOREIGN KEY(organization_id,device_id) REFERENCES devices(organization_id,id));
CREATE TABLE realtime_outbox(id uuid PRIMARY KEY, organization_id uuid NOT NULL, device_id uuid NOT NULL, log_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), attempts integer NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, dispatched_at timestamptz);
CREATE INDEX outbox_pending ON realtime_outbox(next_attempt_at,created_at) WHERE dispatched_at IS NULL;
CREATE TABLE audit_logs(id uuid PRIMARY KEY, organization_id uuid NOT NULL, actor_id uuid NOT NULL, action text NOT NULL, target_id uuid NOT NULL, changes jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
